contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        address owner = c.Owner(); if (__ESBMC_reverted()) return;

        c.withdraw(); if (__ESBMC_reverted()) return;
        c.withdraw{value: amount}(); if (__ESBMC_reverted()) return;

        uint priorBal = address(c).balance;
        uint ownerBalBefore = owner.balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && address(c).balance == 0 && owner.balance == ownerBalBefore + priorBal);
    }

    receive() external payable {}
}

